import json
import logging
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Any, Dict, List, Optional

import openai
from openai import OpenAI

from intent import OllamaManager, OLLAMA_MODEL_NAME

logger = logging.getLogger(__name__)

# Стрип markdown-оберток ```json ... ```
_CODE_FENCE_RE = re.compile(r"^```(?:json)?\s*|\s*```$", re.IGNORECASE)

class ReviewProcessor:
    """
    Модуль анализа и суммаризации отзывов (Map-Reduce архитектура).
    Выполняет требования FR-010 (сводка из 7+ черт) и FR-006 (динамическая таблица).
    """

    def __init__(self, model_name: str = OLLAMA_MODEL_NAME, batch_size: int = 15):
        self.ollama = OllamaManager(model_name=model_name)
        self.client = OpenAI(
            base_url=self.ollama.client_url,
            api_key="ollama",
        )
        self.model_name = model_name
        self.batch_size = batch_size

    def process(self, dm_output: Dict[str, Any]) -> Dict[str, Any]:
        """
        Главный метод оркестрации.
        :param dm_output: Результат работы DataManager (status="ready_for_summary" или "insufficient_data").
        """
        if dm_output.get("status") not in ("ready_for_summary", "insufficient_data"):
            # Если пришел stub, text_only или error — просто возвращаем как есть
            return dm_output

        reviews = dm_output.get("reviews", [])
        game = dm_output.get("game", "Неизвестная игра")
        meta = dm_output.get("meta", {})

        if not reviews:
            return {
                "status": "error",
                "message": "Нет отзывов для анализа.",
                "data": None
            }

        # 1. Сбор предупреждений (FR-008, FR-009)
        warnings = self._extract_warnings(dm_output)

        try:
            # 2. Map-этап (Извлечение фактов)
            logger.info(f"Запуск Map-этапа для {len(reviews)} отзывов...")
            mapped_data = self._map_reviews(reviews, game)
            
            if not any(mapped_data):
                return {
                    "status": "error",
                    "message": "Не удалось извлечь полезную информацию из отзывов.",
                    "data": None
                }

            # 3. Reduce-этап (Генерация текстового саммари)
            logger.info("Запуск Reduce-этапа (Генерация саммари)...")
            summary_md = self._reduce_summary(mapped_data, game)

            # 4. Reduce-этап (Генерация таблицы, если запрошено)
            table_md = None
            # Проверяем sub_tasks из оригинального интента, если передан
            sub_tasks = dm_output.get("sub_tasks", []) 
            if "table" in sub_tasks:
                logger.info("Запуск Reduce-этапа (Генерация таблицы)...")
                table_md = self._reduce_table(mapped_data, game)

            # 5. Формирование финального ответа
            return {
                "status": "success",
                "game": game,
                "summary": summary_md,
                "table": table_md,
                "warnings": warnings,
                "meta": meta
            }

        except Exception as e:
            logger.exception("Критическая ошибка в ReviewProcessor")
            return {
                "status": "error",
                "message": f"Ошибка генерации саммари: {type(e).__name__}: {e}",
                "data": None
            }
        finally:
            # Обязательная выгрузка модели из памяти (NFR-006)
            self.ollama.unload_model()
            logger.info("Модель эмбеддингов выгружена из памяти.")

    # ==========================================
    # Вспомогательные методы
    # ==========================================

    def _extract_warnings(self, dm_output: Dict[str, Any]) -> List[str]:
        warnings = []
        meta = dm_output.get("meta", {})
        
        # FR-008: Уведомление о малом количестве (менее 30)
        if dm_output.get("status") == "insufficient_data" or meta.get("insufficient_data"):
            warnings.append(
                f"Внимание: Найдено менее 30 отзывов. Сводка может быть нерепрезентативной."
            )

        # FR-009: Уведомление об устаревших отзывах (если data_manager передал даты)
        # Ожидается, что DataManager добавит latest_review_date и game_update_date в meta
        if meta.get("latest_review_date") and meta.get("game_update_date"):
            # Простая проверка: если разница в строках больше, чем нужно, или даты переведены в timestamp
            # Здесь предполагаем, что DataManager передает уже разницу в днях для простоты
            if meta.get("days_since_last_review", 0) > 60:
                warnings.append(
                    "Внимание: Последний отзыв был написан более 2 месяцев назад. "
                    "Информация может быть устаревшей."
                )
        
        return warnings

    def _map_reviews(self, reviews: List[str], game: str) -> List[Dict[str, Any]]:
        """Разбивает отзывы на батчи и извлекает факты параллельно."""
        batches = [reviews[i:i + self.batch_size] for i in range(0, len(reviews), self.batch_size)]
        mapped_results = []

        # Параллельный запуск (Ollama может обрабатывать несколько запросов, если позволяет VRAM)
        # max_workers=3 — безопасный лимит для локальной машины
        with ThreadPoolExecutor(max_workers=3) as executor:
            future_to_batch = {
                executor.submit(self._process_batch, batch, game): batch 
                for batch in batches
            }
            
            for future in as_completed(future_to_batch):
                try:
                    result = future.result()
                    if result:
                        mapped_results.append(result)
                except Exception as e:
                    logger.error(f"Ошибка обработки батча: {e}")
                    
        return mapped_results

    def _process_batch(self, batch: List[str], game: str) -> Dict[str, Any]:
        """Обрабатывает один батч отзывов (Map-этап)."""
        prompt = f"""
Ты — аналитик отзывов Steam. Проанализируй предоставленные отзывы на игру "{game}".
Твоя задача — извлечь факты, не додумывая ничего от себя.
Верни строго JSON без markdown-оберток:
{{
  "pros": ["Список плюсов с краткой цитатой из текста"],
  "cons": ["Список минусов с краткой цитатой из текста"],
  "topics": ["Темы, которые обсуждаются, например: оптимизация, сюжет, боссы, цена, баги"]
}}

Отзывы:
{json.dumps(batch, ensure_ascii=False)}
"""
        return self._call_llm(prompt, "Map-этап")

    def _reduce_summary(self, mapped_data: List[Dict[str, Any]], game: str) -> str:
        """Генерирует финальное текстовое саммари (Reduce-этап)."""
        combined_data = json.dumps(mapped_data, ensure_ascii=False)
        
        prompt = f"""
Ты — эксперт по анализу игр. Тебе даны выжимки из отзывов на игру "{game}".
Составь сводку.

КРИТИЧЕСКИЕ ПРАВИЛА (СОБЛЮДАТЬ СТРОГО):
1. Выдели минимум 7 ключевых черт игры.
2. КАЖДАЯ черта должна иметь СВОЮ УНИКАЛЬНУЮ цитату. КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО использовать одну и ту же цитату для разных пунктов!
3. Опирайся ТОЛЬКО на предоставленные данные. Этот пункт преорететние первого. Если в данных нет 7 уникальных фактов — верни столько, сколько есть (например, 4 или 5). НЕ ВЫДУМЫВАЙ факты ради количества.
4. Верни строго JSON без markdown-оберток:
{{
  "summary_points": [
    {{"feature": "Название черты", "description": "Описание", "quote": "Точная цитата из текста"}}
  ]
}}

Данные для анализа:
{combined_data}
"""
        result = self._call_llm(prompt, "Reduce-саммари")
        points = result.get("summary_points", [])
        
        # === ПОСТ-ОБРАБОТКА: Удаление дубликатов цитат ===
        unique_points = []
        seen_quotes = set()
        for p in points:
            # Нормализуем цитату для сравнения (убираем пробелы, приводим к нижнему регистру)
            quote_normalized = re.sub(r'\s+', ' ', p.get('quote', '')).strip().lower()
            
            # Если цитата уже была использована, пропускаем этот пункт (это галлюцинация)
            if quote_normalized in seen_quotes:
                logger.warning(f"Удален дубликат цитаты в пункте: {p.get('feature')}")
                continue
                
            seen_quotes.add(quote_normalized)
            unique_points.append(p)

        if len(unique_points) < 7:
            logger.warning(f"После фильтрации осталось только {len(unique_points)} уникальных черт (из {len(points)}).")

        # Форматируем в Markdown
        md = "### Ключевые особенности игры\n\n"
        for i, p in enumerate(unique_points, 1):
            feature = p.get('feature', 'Особенность')
            desc = p.get('description', '')
            quote = p.get('quote', '')
            md += f"**{i}. {feature}**\n{desc}\n> *{quote}*\n\n"
        return md
    
    def _reduce_table(self, mapped_data: List[Dict[str, Any]], game: str) -> str:
        """Генерирует Markdown-таблицу категорий (Reduce-этап)."""
        combined_data = json.dumps(mapped_data, ensure_ascii=False)
        
        prompt = f"""
Ты — аналитик. На основе выжимок из отзывов на игру "{game}" составь таблицу категорий.

КРИТИЧЕСКИЕ ПРАВИЛА:
1. Включи ТОЛЬКО те категории, которые реально встречаются в данных.
2. Выбери от 3 до 5 самых важных категорий. Не добавляй пустые строки.
3. Для каждой категории найди УНИКАЛЬНУЮ цитату. Не повторяй цитаты из разных категорий.
4. Для каждой черты найди цитату, которая ДОКАЗЫВАЕТ эту черту
5. Верни строго JSON:
{{
  "categories": [
    {{
      "category": "Название", 
      "sentiment": "Положительно/Отрицательно/Смешанно", 
      "description": "Краткое описание", 
      "quote": "Цитата"
    }}
  ]
}}

Данные:
{combined_data}
"""
        result = self._call_llm(prompt, "Reduce-таблица")
        categories = result.get("categories", [])
        
        # === ПОСТ-ОБРАБОТКА ТАБЛИЦЫ ===
        unique_categories = []
        seen_quotes = set()
        for c in categories:
            quote_normalized = re.sub(r'\s+', ' ', c.get('quote', '')).strip().lower()
            if quote_normalized in seen_quotes:
                logger.warning(f"Удалена категория с дубликатом цитаты: {c.get('category')}")
                continue
            seen_quotes.add(quote_normalized)
            unique_categories.append(c)

        # Форматируем в Markdown-таблицу
        md = "### Анализ по категориям\n\n"
        md += "| Категория | Тональность | Описание | Цитата |\n"
        md += "| :--- | :--- | :--- | :--- |\n"
        for c in unique_categories:
            cat = c.get('category', '')
            sent = c.get('sentiment', '')
            desc = c.get('description', '').replace('\n', ' ').replace('|', '\\|') # Экранируем пайпы
            quote = c.get('quote', '').replace('\n', ' ').replace('|', '\\|')
            md += f"| **{cat}** | {sent} | {desc} | *{quote}* |\n"
        
        return md

    def _call_llm(self, prompt: str, stage_name: str, max_retries: int = 2) -> Dict[str, Any]:
        """Универсальный вызов LLM с валидацией JSON и ретраями."""
        messages = [{"role": "system", "content": "Ты возвращаешь только валидный JSON."}]
        messages.append({"role": "user", "content": prompt})

        for attempt in range(max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages,
                    temperature=0.0,
                    max_tokens=1500,
                    response_format={"type": "json_object"},
                )
                raw = response.choices[0].message.content or ""
                cleaned = _CODE_FENCE_RE.sub("", raw.strip()).strip()
                return json.loads(cleaned)

            except json.JSONDecodeError as e:
                logger.warning(f"[{stage_name}] Попытка {attempt+1}: невалидный JSON. {e}")
                messages.append({"role": "user", "content": "Ошибка: невалидный JSON. Верни строго JSON."})
            except (openai.APIConnectionError, openai.APITimeoutError) as e:
                logger.warning(f"[{stage_name}] Попытка {attempt+1}: сетевая ошибка. {e}")
                if attempt == max_retries - 1:
                    raise
            except Exception as e:
                logger.error(f"[{stage_name}] Непредвиденная ошибка: {e}")
                raise

        raise ValueError(f"Не удалось получить валидный JSON на этапе {stage_name} после {max_retries} попыток.")


